import MenuCard from "./MenuCard";

export default function MenuGrid({ menu, addToCart }) {
  if (!Array.isArray(menu)) {
    return <p>Loading menu...</p>;
  }

  return (
    <div className="menu-grid">
      {menu.map(item => {
        // These fields should come from backend:
        // item.avg_rating  (number, e.g. 4.6)
        // item.sales_count (number, e.g. 120)

        const isTopRated = item.avg_rating >= 4.5;
        const isPopular = item.sales_count >= 20;

        return (
          <div key={item.id} className="menu-card-wrapper">
            {(isTopRated || isPopular) && (
              <div className="menu-badges">
                {isPopular && <span className="badge badge-popular">🔥 Popular</span>}
                {isTopRated && <span className="badge badge-rated">⭐ Top Rated</span>}
              </div>
            )}

            <MenuCard item={item} addToCart={addToCart} />
          </div>
        );
      })}
    </div>
  );
}
